-- Slot identity is floor(epoch milliseconds / 300000), matching COVERAGE_EXPECTED_INTERVAL_MS.
WITH r AS (SELECT name, COALESCE(metadata->'sync_delta'->'coverage', metadata->'sync_lint_guards'->'coverage', '{}'::jsonb) AS cov FROM harness_shared.routines WHERE workspace_id='papercusp-workspace' AND name IN ('sync-batch-delta-check','sync-batch-lint-guards')), t AS (SELECT r.name, (r.cov ? 'alarmOpenSinceMs') AS alarm_open, EXISTS (SELECT 1 FROM harness_shared.work_items w WHERE w.workspace_id='papercusp-workspace' AND w.condition_key = CASE r.name WHEN 'sync-batch-delta-check' THEN 'sync-delta-coverage-low' ELSE 'sync-lint-guards-coverage-low' END AND w.status NOT IN ('done','dropped','resolved','closed') AND (w.payload->'_conditionUpsert'->>'lastSeenAt')::timestamptz > now() + interval '1 hour') AS alarm_fresh, count(s.slot) AS slots, count(s.slot) FILTER (WHERE s.evaluated) AS ev, count(s.slot) FILTER (WHERE NOT s.accounted) AS unaccounted FROM r LEFT JOIN LATERAL (SELECT floor((e->>'atMs')::numeric / 300000) AS slot, bool_or(COALESCE((e->>'evaluated')::boolean, false)) AS evaluated, bool_or(COALESCE(e->>'status','') <> '') AS accounted FROM jsonb_array_elements(COALESCE(r.cov->'ticks','[]'::jsonb)) e WHERE (e->>'atMs')::bigint > (extract(epoch from now())*1000)::bigint - 86400000 AND (e->>'atMs')::bigint <= (extract(epoch from now())*1000)::bigint GROUP BY floor((e->>'atMs')::numeric / 300000)) s ON true GROUP BY r.name, r.cov) SELECT count(*)::int AS routines, COALESCE(min(slots), 0)::int AS min_slots, COALESCE(min(CASE WHEN slots > 0 THEN ev::float8 / slots ELSE 0 END), 0)::float8 AS min_ratio, COALESCE(sum(unaccounted), 0)::int AS unaccounted_slots, count(*) FILTER (WHERE COALESCE(ev::float8 / NULLIF(slots, 0), 0) < 0.95 AND NOT (alarm_open AND alarm_fresh))::int AS low_without_current_alarm, (CASE WHEN count(*) = 2 AND bool_and(slots >= 276 AND unaccounted = 0 AND (ev::float8 / NULLIF(slots, 0) >= 0.95 OR (alarm_open AND alarm_fresh))) THEN 1 ELSE 0 END)::int AS accounted FROM t;
